import React, { Fragment, useCallback, useEffect, useState } from 'react'
import { Form, Input, Button, Space, Skeleton, Select } from 'antd'
import { connect, useDispatch, useSelector } from 'react-redux'
import { postData } from '../../../../Actions/Action'

const { Option } = Select

const initialValues = {
	customer_id: '',
	user_name: '',
	password: '',
	access_key: '',
}

function ConnectionSettingsComponent(props) {
	const [connectionState, setConnectionState] = useState({
		testType: false,
		skeleton_loading: true,
	})
	const [apiType, setApiType] = useState('GTZ')
	const [state, setState] = useState({
		global_tranz: initialValues,
		cerasis: initialValues,
	})
	// const { carrier_type } = useSelector(state => state)
	const dispatch = useDispatch()

	useEffect(() => {
		if (
			props.connectionSettings &&
			props.connectionSettings !== null &&
			typeof props.connectionSettings === 'object' &&
			Object.keys(props.connectionSettings).length > 1
		) {
			setApiType(props.connectionSettings?.api_type || 'GTZ')
			setState({
				global_tranz: {
					...initialValues,
					...props.connectionSettings?.global_tranz,
				},
				cerasis: { ...initialValues, ...props.connectionSettings?.cerasis },
			})
			setConnectionState(prevState => ({
				...prevState,
				skeleton_loading: false,
			}))

			dispatch({
				type: 'SET_CARRIER_TYPE',
				payload: props.connectionSettings?.api_type || 'GTZ',
			})
		}
	}, [dispatch, props.connectionSettings])

	const handleStateChange = useCallback((e, index) => {
		setState(prevState => ({
			...prevState,
			[index]: {
				...prevState[index],
				[e.target.name]: e.target.value,
			},
		}))
	}, [])

	const handleTypeChange = type => {
		setConnectionState({ ...connectionState, testType: type })
	}

	const onFinish = values => {
		values = {
			testType: connectionState.testType,
			installed_carrier_id: props.carrierId,
			carrierId: props.carrierId,
			api_type: apiType,
			...state,
		}

		props.postData(values, props.token)
	}

	if (props.connectionSettings === null || props.connectionSettings === undefined) {
		return <Skeleton active />
	} else {
		if (Object.keys(props.connectionSettings)?.length === 0) {
			props.connectionSettings.access_level = 'pro'
		}
	}

	return (
		!connectionState.skeleton_loading && (
			<Fragment>
				<div className={'note-bx'}>
					<strong>Note!</strong> You must have a GlobalTranz account to use this
					application. If you do not have one contact GlobalTranz at
					866-275-1407.
				</div>
				<Form
					layout='vertical'
					name='connection_settings'
					className='connection-settings'
					size={'large'}
					onFinish={onFinish}>
					<Form.Item label='Which API Will You Connect To?' name='api_type'>
						<Select
							defaultValue={apiType}
							value={apiType}
							onChange={type => {
								setApiType(type)
								dispatch({
									type: 'SET_CARRIER_TYPE',
									payload: type,
								})

								dispatch({
									type: 'GET_SERVICES',
									payload: null,
								})
								dispatch({
									type: 'SAVE_CARRIER_TAB_SETTINGS',
									payload: null,
								})
							}}>
							<Option value='GTZ'>GlobalTranz</Option>
							<Option value='CRS'>Cerasis</Option>
						</Select>
					</Form.Item>

					{apiType === 'GTZ' ? (
						<>
							<Form.Item
								label='Customer ID'
								// name='gtz_customer_id'
								rules={[{ required: true, message: 'Customer ID' }]}
								requiredMark
								required>
								<Input
									name='customer_id'
									placeholder='Customer ID'
									value={state.global_tranz.customer_id}
									onChange={e => handleStateChange(e, 'global_tranz')}
									required
								/>
							</Form.Item>

							<Form.Item
								label='Username'
								// name='gtz_user_name'
								rules={[{ required: true, message: 'Username' }]}
								requiredMark
								required>
								<Input
									name='user_name'
									placeholder='Username'
									value={state.global_tranz.user_name}
									onChange={e => handleStateChange(e, 'global_tranz')}
									required
								/>
							</Form.Item>

							<Form.Item
								label='Password'
								// name='gtz_password'
								rules={[{ required: true, message: 'Password' }]}
								requiredMark
								required>
								<Input
									name='password'
									type='text'
									placeholder='Password'
									value={state.global_tranz.password}
									onChange={e => handleStateChange(e, 'global_tranz')}
									required
								/>
							</Form.Item>

							<Form.Item
								label='Access Key'
								// name='gtz_access_key'
								rules={[{ required: true, message: 'Access Key' }]}
								requiredMark
								required>
								<Input
									name='access_key'
									placeholder='Access Key'
									value={state.global_tranz.access_key}
									onChange={e => handleStateChange(e, 'global_tranz')}
									required
								/>
							</Form.Item>
						</>
					) : (
						<>
							<Form.Item
								label='Shipper ID'
								// name='cerasis_customer_id'
								rules={[{ required: true, message: 'Shipper ID' }]}
								requiredMark
								required>
								<Input
									name='customer_id'
									placeholder='Shipper ID'
									value={state.cerasis.customer_id}
									onChange={e => handleStateChange(e, 'cerasis')}
									required
								/>
							</Form.Item>

							<Form.Item
								label='Username'
								// name='cerasis_user_name'
								rules={[{ required: true, message: 'Username' }]}
								requiredMark
								required>
								<Input
									name='user_name'
									placeholder='Username'
									value={state.cerasis.user_name}
									onChange={e => handleStateChange(e, 'cerasis')}
									required
								/>
							</Form.Item>

							<Form.Item
								label='Password'
								// name='cerasis_password'
								rules={[{ required: true, message: 'Password' }]}
								requiredMark
								required>
								<Input
									name='password'
									type='text'
									placeholder='Password'
									value={state.cerasis.password}
									onChange={e => handleStateChange(e, 'cerasis')}
									required
								/>
							</Form.Item>

							<Form.Item
								label='Access Key'
								// name='cerasis_access_key'
								rules={[{ required: true, message: 'Access Key' }]}
								requiredMark
								required>
								<Input
									name='access_key'
									placeholder='Access Key'
									value={state.cerasis.access_key}
									onChange={e => handleStateChange(e, 'cerasis')}
									required
								/>
							</Form.Item>
						</>
					)}

					<Form.Item style={{ textAlign: 'right', marginBottom: '0' }}>
						<Space>
							<Button
								type='primary'
								size={'large'}
								htmlType='submit'
								name={`test`}
								onClick={() => handleTypeChange(true)}>
								Test Connection
							</Button>
							<Button
								type='primary'
								size={'large'}
								htmlType='submit'
								name={`save`}
								onClick={() => handleTypeChange(false)}>
								Save Settings
							</Button>
						</Space>
					</Form.Item>
				</Form>
			</Fragment>
		)
	)
}

const mapStateToProps = state => {
	return {
		connectionSettings: state.connectionSettings,
		skeleton_loading: state.skeleton_loading,
		token: state.token,
		carrierId: state.carrierId,
	}
}

const mapDispatchToProps = dispatch => {
	return {
		postData: (data, token) =>
			dispatch(
				postData(
					data,
					'GET_CONNECTION_SETTINGS',
					'submit_connection_settings',
					token
				)
			),
	}
}

export default connect(mapStateToProps, mapDispatchToProps)(ConnectionSettingsComponent)
